 class=\"okh-actions\" aria-label=\"可用行动\">\n          <button type=\"button\" class=\"okh-action okh-action-main\" data-draft=\"我走到伊丝娜的房门前，轻轻敲了敲门。\">敲门拜访</button>\n          <button type=\"button\" class=\"okh-action\" data-draft=\"我在伊丝娜的房门外留下一张口信：\">留下口信</button>\n        </div>\n\n        <details class=\"okh-fold\"><summary>同行经历</summary><div data-dossier-journey></div></details>\n        <details class=\"okh-fold\">\n          <summary>档案图册 <span class=\"okh-count\">5 张</span></summary>\n          <div class=\"okh-thumbs\">\n            <button type=\"button\" class=\"okh-thumb\" data-art=\"neutral\" aria-label=\"查看平日头像\" aria-current=\"true\"><img src=\"data:image/webp;base64,\" alt=\"\" width=\"176\" height=\"220\"></button>\n            <button type=\"button\" class=\"okh-thumb\" data-art=\"smile\" aria-label=\"查看微笑头像\"><img src=\"data:image/webp;base64,\" alt=\"\" width=\"176\" height=\"220\"></button>\n            <button type=\"button\" class=\"okh-thumb\" data-art=\"focus\" aria-label=\"查看凝神头像\"><img src=\"data:image/webp;base64,\" alt=\"\" width=\"176\" height=\"220\"></button>\n            <button type=\"button\" class=\"okh-thumb\" data-art=\"clothed\" aria-label=\"查看斥候装全身\"><img src=\"data:image/webp;base64,\" alt=\"\" width=\"720\" height=\"1080\"></button>\n            <button type=\"button\" class=\"okh-thumb\" data-art=\"casual\" aria-label=\"查看日常装全身\"><img src=\"data:image/webp;base64,\" alt=\"\" width=\"720\" height=\"1080\"></button>\n          </div>\n        </details>\n      </div>\n    </div>\n\n    <section class=\"okh-module-view\" data-view=\"module\" aria-labelledby=\"okh-isna-view-title\" hidden>\n      <img data-module-art alt=\"\" width=\"900\" height=\"300\">\n      <p data-module-empty>暂无记录</p>\n      <div class=\"okh-body-layout\" data-module-body hidden>\n        <div class=\"okh-body-left\">\n        <div class=\"okh-outfit-group\" role=\"group\" aria-label=\"插图版本\" data-outfit-group>\n          <button type=\"button\" data-outfit=\"clothed\" aria-pressed=\"true\">着衣</button>\n          <button type=\"button\" data-outfit=\"underwear\" aria-pressed=\"false\">内衣</button>\n        </div>\n          <div class=\"okh-silhouette-row\">\n        <figure class=\"okh-body-figure\" aria-label=\"伊丝娜的部位图\">\n      <img class=\"okh-module-silhouette\" src=\"data:image/webp;base64,\" alt=\"伊丝娜的正面全身剪影\" width=\"1024\" height=\"1536\">\n          <span class=\"okh-body-highlight\" aria-hidden=\"true\"></span>\n          <button class=\"okh-body-hit\" type=\"button\" data-part-hit=\"head\" aria-label=\"查看头部\" aria-controls=\"okh-isna-part-details\"\n            style=\"--hit-x:49.79%;--hit-y:10.83%;--hit-w:25.62%;--hit-h:14.44%\"></button>\n          <button class=\"okh-body-hit\" type=\"button\" data-part-hit=\"chest\" aria-label=\"查看胸口\" aria-controls=\"okh-isna-part-details\"\n            style=\"--hit-x:50%;--hit-y:27.2%;--hit-w:21%;--hit-h:9%\"></button>\n          <button class=\"okh-body-hit\" type=\"button\" data-part-hit=\"hips\" aria-label=\"查看胯部\" aria-controls=\"okh-isna-part-details\"\n            style=\"--hit-x:49.79%;--hit-y:40%;--hit-w:24.17%;--hit-h:14.17%\"></button>\n          <button class=\"okh-body-hit\" type=\"button\" data-part-hit=\"legs\" aria-label=\"查看腿部\" aria-controls=\"okh-isna-part-details\"\n            style=\"--hit-x:49.685%;--hit-y:68.61%;--hit-w:26.25%;--hit-h:42.78%\"></button>\n          <button class=\"okh-body-hit\" type=\"button\" data-part-hit=\"hands\" aria-label=\"查看图左手部\" aria-controls=\"okh-isna-part-details\"\n            style=\"--hit-x:31.25%;--hit-y:50.56%;--hit-w:6.46%;--hit-h:8.33%\"></button>\n          <button class=\"okh-body-hit\" type=\"button\" data-part-hit=\"hands\" aria-label=\"查看图右手部\" aria-controls=\"okh-isna-part-details\"\n            style=\"--hit-x:67.29%;--hit-y:50.56%;--hit-w:6.25%;--hit-h:8.33%\"></button>\n          <div class=\"okh-part-popover\" id=\"okh-isna-part-popover\" data-part-popover role=\"tooltip\" hidden>\n            <strong></strong>\n            <p></p>\n            <dl><dt>性行为次数</dt><dd data-part-popover-count>未记录</dd></dl>\n          </div>\n        </figure>\n          </div>\n        </div>\n        <section class=\"okh-body-details\" aria-label=\"角色记录与部位详情\">\n          <div id=\"okh-isna-part-details\" aria-live=\"polite\" aria-atomic=\"true\">\n            <div data-part-records>\n              <h2 class=\"okh-part-heading\">记录</h2>\n              <dl class=\"okh-facts okh-record-facts\">\n                <div><dt>是否处女</dt><dd data-dossier-stat=\"virginity\">未记录</dd></div>\n                <div><dt>最近一周性行为次数</dt><dd data-dossier-stat=\"recent\">未记录</dd></div>\n                <div><dt>最后一次性行为的体位</dt><dd data-dossier-stat=\"position\">未记录</dd></div>\n                <div><dt>被内射次数</dt><dd data-dossier-stat=\"internal\">未记录</dd></div>\n                <div><dt>精液总容量</dt><dd data-dossier-stat=\"volume\" data-total-volume>未记录</dd></div>\n              </dl>\n            </div>\n            <div data-part-specific hidden>\n              <h2 class=\"okh-part-heading\" data-part-heading></h2>\n              <img class=\"okh-part-art\" data-part-image width=\"440\" height=\"440\" alt=\"\">\n              <dl class=\"okh-facts okh-part-facts\" data-part-facts></dl>\n            </div>\n          </div>\n        </section>\n      </div>\n    </section>\n\n    <figure class=\"okh-light\" data-view=\"image\" hidden>\n      <img alt=\"\" width=\"176\" height=\"220\">\n      <figcaption>\n        <span data-caption></span>\n        <button type=\"button\" class=\"okh-action\" data-default></button>\n      </figcaption>\n    </figure>\n\n    <div class=\"okh-roster\" data-view=\"roster\" hidden>\n      <button type=\"button\" class=\"okh-roster-row\" data-open aria-label=\"打开伊丝娜档案\">\n        <img src=\"data:image/webp;base64,\" alt=\"\" width=\"49\" height=\"55\">\n        <span><strong>伊丝娜</strong><small>猫族游侠</small></span>\n        <span>角色档案 ›</span>\n      </button>\n      <button type=\"button\" class=\"okh-quiet\" data-unified-roster>返回同伴名册</button>\n      <label for=\"okh-isna-draft\">行动草稿</label>\n      <textarea id=\"okh-isna-draft\" rows=\"2\"></textarea>\n      <p class=\"okh-feedback\" role=\"status\"></p>\n    </div>\n  </section>\n\n  </div>",
      mount(document, window, rosterPortrait) {
    (() => {
      const root = document.getElementById("okh-isna-dossier-unified-light");
      const find = (selector) => root.querySelector(selector);
      const heading = find("[data-heading]");
      const back = find("[data-back]");
      const portrait = find("[data-portrait]");
      const displayImage = find('[data-view="image"] img');
      const moduleArt = find("[data-module-art]");
      const moduleView = find('[data-view="module"]');
      const moduleEmpty = find("[data-module-empty]");
      const moduleBody = find("[data-module-body]");
      const partPopover = find("[data-part-popover]");
      const partFigure = find(".okh-body-figure");
      const detailsPanel = find(".okh-body-details");
      const popoverCount = find("[data-part-popover-count]");
      const partRecords = find("[data-part-records]");
      const partSpecific = find("[data-part-specific]");
      const partTitle = find("[data-part-heading]");
      const partImage = find("[data-part-image]");
      const partFacts = find("[data-part-facts]");
      const hotspots = [...moduleBody.querySelectorAll("[data-part-hit]")];
      const activity = { totalVolumeMl: null, encountersByPart: {} };
      root.addEventListener("okh:encounters", ({ detail }) => {
        activity.encountersByPart = detail.encountersByPart;
        root.querySelectorAll("[data-dossier-stat]").forEach(field => {
          field.textContent = detail[field.dataset.dossierStat];
        });
        displayedPart = null;
        showPartPopover();
      });
      const parts = {
        head: {
          title: "头部", summary: "绯红卷发，金色竖瞳", artAlt: "伊丝娜的猫耳、绯红卷发与金色竖瞳", image: "data:image/webp;base64,",
          facts: [
            ["猫耳与发色", "赤褐色猫耳立在头顶，绯红波浪长发垂至肩头。"],
            ["眼睛与神态", "金色竖瞳。笑起来，唇边露出一点小虎牙。"]
          ]
        },
        chest: {
          title: "胸口", summary: "黑色三角罩杯与细系带", artAlt: "伊丝娜的黑色三角罩杯内衣", image: "data:image/webp;base64,",
          facts: [
            ["装束", "短三角罩杯的下缘抬高，保留下胸弧线。罩杯边缘贴合，细系带拉紧后在胸前汇合并连到颈带。"]
          ]
        },
        hips: {
          title: "胯部", summary: "赤红猫尾从尾椎伸出，向上回弯", artAlt: "伊丝娜臀胯后侧，赤红猫尾从尾椎伸出并向上回弯", image: "data:image/webp;base64,",
          facts: [
            ["装束", "深蓝色高腰线内裤，臀胯由腰线向下自然展开。"],
            ["猫尾", "赤红色，从尾椎处伸出，向上弯成 S 形，尾尖向内回钩。"]
          ]
        },
        legs: {
          title: "腿部", summary: "落脚轻，穿黑色软底短靴", artAlt: "伊丝娜的双腿和黑色软底短靴", image: "data:image/webp;base64,",
          facts: [
            ["步态", "身手轻巧，擅长潜行和在狭窄处腾挪。"],
            ["短靴", "黑色软底皮靴，靴底藏有应急用的骨粉。"]
          ]
        },
        hands: {
          title: "手部", summary: "擅长开锁与拆解机关", artAlt: "伊丝娜自然放松的双手", image: "data:image/webp;base64,",
          facts: [
            ["手上功夫", "随身带黄铜开锁工具，擅长拆陷阱，也惯用双匕首。"]
          ]
        }
      };
      const clothedParts = {"chest": {"title": "胸口", "summary": "灰墨绿露肩上装，菱形扣下有水滴形镂空", "artAlt": "伊丝娜 · 灰墨绿露肩上装，菱形扣下有水滴形镂空", "image": "data:image/webp;base64,", "facts": [["装束", "灰墨绿露肩上装，菱形扣下有水滴形镂空。"]]}, "hips": {"title": "胯部", "summary": "炭灰短裤、腿带与猫尾", "artAlt": "伊丝娜 · 炭灰短裤、腿带与猫尾", "image": "data:image/webp;base64,", "facts": [["装束", "炭灰短裤、腿带与猫尾。"]]}, "legs": {"title": "腿部", "summary": "裸腿、皮带与黑色短靴", "artAlt": "伊丝娜 · 裸腿、皮带与黑色短靴", "image": "data:image/webp;base64,", "facts": [["装束", "裸腿、皮带与黑色短靴。"]]}, "hands": {"title": "手部", "summary": "灰墨绿袖口与旧黄铜扣", "artAlt": "伊丝娜 · 灰墨绿袖口与旧黄铜扣", "image": "data:image/webp;base64,", "facts": [["装束", "灰墨绿袖口与旧黄铜扣。"]]}};
      const caption = find("[data-caption]");
      const setDefault = find("[data-default]");
      const reopen = find("[data-open]");
      const draft = find("textarea");
      const feedback = find("[role=status]");
      const thumbs = [...root.querySelectorAll("[data-art]")];
      const panels = [...root.querySelectorAll("[data-view]")];
      const images = {
        neutral: { label: "平日", src: portrait.querySelector("img").src },
        smile: { label: "微笑", src: find('[data-art="smile"] img').src },
        focus: { label: "凝神", src: find('[data-art="focus"] img').src }
      };
      images["clothed"] = {label: "斥候装全身", src: find('[data-art="clothed"] img').src};
      images["casual"] = {label: "日常装全身", src: find('[data-art="casual"] img').src};
      const headings = { dossier: "角色档案", image: "档案图册", roster: "同伴名册" };
      let chosen = "neutral";
      if (rosterPortrait) {
        images.roster = { label: "默认立绘", src: rosterPortrait };
        chosen = "roster";
        portrait.querySelector("img").src = rosterPortrait;
      }
      let enlarged = "neutral";
      let activeView = "dossier";
      let imageTrigger = portrait;
      let moduleTrigger;
      let hoveredPart = null;
      let focusedPart = null;
      let pinnedPart = null;
      let describedPart = null;
      let displayedPart = null;
      let outfit = "clothed";
      let hoverTimer;

      function amount(value, unit) {
        return Number.isFinite(value) && value >= 0 ? `${value} ${unit}` : "未记录";
      }

      function partCount(key) {
        return amount(activity.encountersByPart[key], "次");
      }

      find("[data-total-volume]").textContent = amount(activity.totalVolumeMl, "mL");

      function getPart(key) {
        return (outfit === "clothed" ? clothedParts[key] : undefined) ?? parts[key] ?? null;
      }

      function displayPart(key) {
        const part = getPart(key);
        if (displayedPart === part) return;
        displayedPart = part;
        partRecords.hidden = Boolean(key);
        partSpecific.hidden = !key;
        partFigure.dataset.region = key ?? "";
        if (!key) return;
        partTitle.textContent = part.title;
        partImage.src = part.image;
        partImage.alt = part.artAlt;
        const facts = [...part.facts, ["性行为次数", partCount(key)]];
        partFacts.replaceChildren(...facts.map(([label, value]) => {
          const row = document.createElement("div");
          const term = document.createElement("dt");
          const description = document.createElement("dd");
          term.textContent = label;
          description.textContent = value;
          row.append(term, description);
          return row;
        }));
      }

      function positionPartPopover(trigger) {
        const frame = partFigure.getBoundingClientRect();
        const target = trigger.getBoundingClientRect();
        const width = partPopover.offsetWidth;
        const height = partPopover.offsetHeight;
        const gap = 8;
        const detailsLeft = detailsPanel.getBoundingClientRect().left;
        const rightLimit = Math.max(frame.width, detailsLeft - frame.left - gap);
        const onRight = target.right - frame.left + gap;
        const onLeft = target.left - frame.left - width - gap;
        const above = target.top - frame.top - height - gap;
        const below = target.bottom - frame.top + gap;
        let x = (target.left + target.right) / 2 - frame.left + gap;
        let y = above >= 0 ? above : below;
        if (onRight + width <= rightLimit || onLeft >= 0) {
          x = onRight + width <= rightLimit ? onRight : onLeft;
          y = (target.top + target.bottom - height) / 2 - frame.top;
        }
        x = Math.max(0, Math.min(x, rightLimit - width));
        y = Math.max(0, Math.min(y, frame.height - height));
        partPopover.style.setProperty("--popover-left", `${x}px`);
        partPopover.style.setProperty("--popover-top", `${y}px`);
      }

      function showPartPopover() {
        const trigger = hoveredPart || focusedPart || pinnedPart;
        displayPart(trigger?.dataset.partHit ?? null);
        if (describedPart !== trigger) {
          describedPart?.removeAttribute("aria-describedby");
          trigger?.setAttribute("aria-describedby", partPopover.id);
          describedPart = trigger;
        }
        partPopover.hidden = !trigger;
        if (!trigger) return;
        const key = trigger.dataset.partHit;
        const part = getPart(key);
        partPopover.querySelector("strong").textContent = part.title;
        partPopover.querySelector("p").textContent = part.summary;
        popoverCount.textContent = partCount(key);
        positionPartPopover(trigger);
      }

      function endHover() {
        clearTimeout(hoverTimer);
        hoverTimer = setTimeout(() => {
          hoveredPart = null;
          showPartPopover();
        }, 140);
      }

      function dismissPartPopover() {
        clearTimeout(hoverTimer);
        hoveredPart = null;
        focusedPart = null;
        pinPart(null);
        showPartPopover();
      }

      function pinPart(trigger) {
        pinnedPart = trigger;
        hotspots.forEach(hit => hit.setAttribute("aria-pressed", String(hit === trigger)));
      }

      const outfitTabs = [...find("[data-outfit-group]").querySelectorAll("[data-outfit]")];
      outfitTabs.forEach(tab => {
        tab.addEventListener("click", () => {
          outfit = tab.dataset.outfit;
          outfitTabs.forEach(option => option.setAttribute("aria-pressed", String(option === tab)));
          showPartPopover();
        });
      });

      pinPart(null);
      hotspots.forEach((hit) => {
        hit.addEventListener("pointerenter", (event) => {
          if (event.pointerType === "touch") return;
          clearTimeout(hoverTimer);
          hoveredPart = hit;
          showPartPopover();
        });
        hit.addEventListener("pointerleave", (event) => {
          if (event.pointerType !== "touch") endHover();
        });
        hit.addEventListener("focus", () => {
          focusedPart = hit;
          showPartPopover();
        });
        hit.addEventListener("blur", () => {
          if (focusedPart === hit) focusedPart = null;
          showPartPopover();
        });
        hit.addEventListener("click", () => {
          if (pinnedPart === hit) {
            dismissPartPopover();
            return;
          }
          pinPart(hit);
          showPartPopover();
        });
      });
      partPopover.addEventListener("pointerenter", () => clearTimeout(hoverTimer));
      partPopover.addEventListener("pointerleave", endHover);
      window.addEventListener("resize", showPartPopover);
      moduleBody.addEventListener("click", (event) => {
        if (!event.target.closest("[data-part-hit], [data-part-popover], [data-outfit-group]")) dismissPartPopover();
      });

      function show(view, focus) {
        if (view !== "module") dismissPartPopover();
        activeView = view;
        heading.textContent = view === "module" ? moduleTrigger.getAttribute("aria-label") : headings[view];
        panels.forEach((panel) => { panel.hidden = panel.dataset.view !== view; });
        back.hidden = view === "roster";
        back.textContent = view === "image" || view === "module" ? "返回档案　×" : "返回名册　×";
        focus.focus({ preventScroll: true });
        root.scrollIntoView({ block: "nearest" });
      }

      function syncDefault() {
        const portraitImage = portrait.querySelector("img");
        portraitImage.src = images[chosen].src;
        portraitImage.alt = "伊丝娜 · " + images[chosen].label;
        reopen.querySelector("img").src = images[chosen].src;
        thumbs.forEach((thumb) => {
          if (thumb.dataset.art === chosen) thumb.setAttribute("aria-current", "true");
          else thumb.removeAttribute("aria-current");
        });
        setDefault.disabled = enlarged === chosen;
        setDefault.textContent = setDefault.disabled ? "当前默认立绘" : "设为默认立绘";
      }

      function openImage(key, trigger) {
        enlarged = key;
        imageTrigger = trigger;
        const entry = images[key];
        displayImage.src = entry.src;
        displayImage.alt = "伊丝娜 · " + entry.label;
        caption.textContent = displayImage.alt;
        syncDefault();
        show("image", back);
      }

      back.addEventListener("click", () => {
        if (activeView === "image") show("dossier", imageTrigger);
        else if (activeView === "module") show("dossier", moduleTrigger);
        else root.dispatchEvent(new CustomEvent("okh:roster", { bubbles: true }));
      });
      root.querySelectorAll("[data-module]").forEach((entry) => {
        entry.addEventListener("click", () => {
          moduleTrigger = entry;
          const module = entry.dataset.module;
          const isSilhouette = module === "sigil";
          moduleView.dataset.openModule = module;
          moduleArt.hidden = isSilhouette;
          moduleEmpty.hidden = isSilhouette;
          moduleBody.hidden = !isSilhouette;
          if (!isSilhouette) moduleArt.src = entry.querySelector("img").src;
          show("module", back);
        });
      });
      root.addEventListener("keydown", (event) => {
        if (event.key === "Escape" && !back.hidden) {
          event.preventDefault();
          if (!partPopover.hidden) dismissPartPopover();
          else back.click();
        }
      });
