      function positionPartPopover(trigger) {
        const frame = partFigure.getBoundingClientRect();
        const target = trigger.getBoundingClientRect();
        const width = partPopover.offsetWidth;
        const height = partPopover.offsetHeight;
        const gap = 8;
        const detailsLeft = detailsPanel.getBoundingClientRect().left;
        const rightLimit = Math.max(frame.width, detailsLeft - frame.left - gap);
        const onRight = target.right - frame.left + gap;
        const onLeft = target.left - frame.left - width - gap;
        const above = target.top - frame.top - height - gap;
        const below = target.bottom - frame.top + gap;
        let x = (target.left + target.right) / 2 - frame.left + gap;
        let y = above >= 0 ? above : below;
        if (onRight + width <= rightLimit || onLeft >= 0) {
          x = onRight + width <= rightLimit ? onRight : onLeft;
          y = (target.top + target.bottom - height) / 2 - frame.top;
        }
        x = Math.max(0, Math.min(x, rightLimit - width));
        y = Math.max(0, Math.min(y, frame.height - height));
        partPopover.style.setProperty("--popover-left", `${x}px`);
        partPopover.style.setProperty("--popover-top", `${y}px`);
      }

      function showPartPopover() {
        const trigger = hoveredPart || focusedPart || pinnedPart;
        displayPart(trigger?.dataset.partHit ?? null);
        if (describedPart !== trigger) {
          describedPart?.removeAttribute("aria-describedby");
          trigger?.setAttribute("aria-describedby", partPopover.id);
          describedPart = trigger;
        }
        partPopover.hidden = !trigger;
        if (!trigger) return;
        const key = trigger.dataset.partHit;
        const part = getPart(key);
        partPopover.querySelector("strong").textContent = part.title;
        partPopover.querySelector("p").textContent = part.summary;
        popoverCount.textContent = partCount(key);
        positionPartPopover(trigger);
      }

      function endHover() {
        clearTimeout(hoverTimer);
        hoverTimer = setTimeout(() => {
          hoveredPart = null;
          showPartPopover();
        }, 140);
      }

      function dismissPartPopover() {
        clearTimeout(hoverTimer);
        hoveredPart = null;
        focusedPart = null;
        pinPart(null);
        showPartPopover();
      }

      function pinPart(trigger) {
        pinnedPart = trigger;
        hotspots.forEach(hit => hit.setAttribute("aria-pressed", String(hit === trigger)));
