          clearTimeout(hoverTimer);
          hoveredPart = hit;
          showPartPopover();
        });
        hit.addEventListener("pointerleave", (event) => {
          if (event.pointerType !== "touch") endHover();
        });
        hit.addEventListener("focus", () => {
          focusedPart = hit;
          showPartPopover();
        });
        hit.addEventListener("blur", () => {
          if (focusedPart === hit) focusedPart = null;
          showPartPopover();
        });
        hit.addEventListener("click", () => {
          if (pinnedPart === hit) {
            dismissPartPopover();
            return;
          }
          pinPart(hit);
          showPartPopover();
        });
      });
      partPopover.addEventListener("pointerenter", () => clearTimeout(hoverTimer));
      partPopover.addEventListener("pointerleave", endHover);
      window.addEventListener("resize", showPartPopover);
